public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int mod = scanner.nextInt();
        int k = scanner.nextInt();
        int t = 1;
        int j = 1;
        for (int i = 1; i < mod; ++i) {
            t = (int)((long)t * k % mod);
            if (t == 1) {
                j = i;
                break;
            }
        }
        if (k == 0) j = 1;
        long ans = 1;
        int limit = (mod - 1) / j;
        for (int i = 1; i <= limit; ++i) {
            ans = (ans * mod) % 1000000007;
        }
        if (k == 1) {
            ans = (ans * mod) % 1000000007;
        }
        System.out.println(ans);
        scanner.close();
    }
}
